package app.bolbol.tv.journeys

import android.content.Intent
import android.graphics.Rect
import android.os.SystemClock
import androidx.benchmark.macro.MacrobenchmarkScope
import androidx.test.uiautomator.By
import androidx.test.uiautomator.UiDevice
import androidx.test.uiautomator.UiObject2

/*
 * User journeys shared by the two instrumentation modules:
 *   :baselineprofile (BaselineProfileGenerator) and :benchmark (Startup/HomeScroll/OpenDetails).
 * The source set is declared once, here, and added to both modules (see their build files), so the
 * profile is generated by exactly the flows that are benchmarked.
 *
 * Everything is D-pad driven through UiAutomator. The UI is Persian RTL, so LEFT moves FORWARD along a
 * row and RIGHT moves back. The app has no resource ids yet: the waits below use "a card has focus"
 * (Compose TV requests focus on the first poster as soon as the rows are drawn) plus bounded idle
 * waits. The optional test-tag hooks in [UiHooks] make the details/browse waits exact; they are
 * listed in docs/perf-budget.md (§"UI hooks the journeys can use").
 */

const val TARGET_PACKAGE = "app.bolbol.tv"
const val TARGET_ACTIVITY = "app.bolbol.tv.MainActivity"

/** Top bar tab label «فیلم» (exactly as in feature/home `home_tabs`). */
const val TAB_MOVIES = "فیلم"

/**
 * Optional hooks the UI may add (nothing breaks while they are missing).
 * Test tags are visible to UiAutomator as resource ids only when the root composable sets
 * `Modifier.semantics { testTagsAsResourceId = true }`.
 */
object UiHooks {
    /** testTag on the details screen root. */
    const val DETAILS_SCREEN = "details_screen"

    /** `trace("details_ready") { }` section: details opened (OK pressed) until its content is drawn. */
    const val TRACE_DETAILS_READY = "details_ready"
}

// ---- timing ---------------------------------------------------------------------------------------
/** Cold start plus the first feed: cached rows paint at once, the very first run needs the network. */
private const val HOME_TIMEOUT_MS = 30_000L
private const val GRID_TIMEOUT_MS = 15_000L

/** Upper bound for UiAutomator's "no accessibility events" wait after each key press. */
private const val IDLE_TIMEOUT_MS = 1_500L

/** Pause after a key press, so the run looks like a person with a remote (hero debounce is 300 ms). */
private const val KEY_SETTLE_MS = 150L
private const val DETAILS_WAIT_MS = 2_000L
private const val BROWSE_OPEN_MS = 1_500L
private const val POLL_MS = 200L

/** The hero (backdrop + title) takes 44 % of the home screen; the first card row starts below it. */
private const val HOME_HERO_FRACTION = 0.44f

/** Browse: the fixed header (title + chips) ends above this fraction; the first poster row is below. */
private const val BROWSE_HEADER_FRACTION = 0.25f

/** A focused card is small. A focused node covering more than this is the Compose host view, not a card. */
private const val MAX_CARD_AREA_FRACTION = 0.25f

private const val MAX_FOCUS_STEPS = 12

// ---- launching ------------------------------------------------------------------------------------
/**
 * The app declares only LEANBACK_LAUNCHER (no LAUNCHER category), so launch the activity explicitly
 * instead of relying on `getLaunchIntentForPackage`.
 */
fun launchIntent(): Intent = Intent(Intent.ACTION_MAIN).apply {
    addCategory(Intent.CATEGORY_LEANBACK_LAUNCHER)
    setClassName(TARGET_PACKAGE, TARGET_ACTIVITY)
    addFlags(Intent.FLAG_ACTIVITY_NEW_TASK or Intent.FLAG_ACTIVITY_CLEAR_TASK)
}

// ---- journey 1: startup ---------------------------------------------------------------------------
/** Launch, then wait until the first poster row is drawn and holds focus. */
fun MacrobenchmarkScope.startToHome() {
    startActivityAndWait(launchIntent())
    waitForHomeRows()
}

/** Blocks until a card below the hero has focus; fails loudly instead of recording an empty journey. */
fun MacrobenchmarkScope.waitForHomeRows() {
    val shown = pollUntil(HOME_TIMEOUT_MS) { device.cardFocusedBelow(HOME_HERO_FRACTION) }
    check(shown) {
        "Home rows were not drawn within ${HOME_TIMEOUT_MS / 1000} s " +
            "(no card below the hero got focus). Is the device online, and is the feed reachable?"
    }
    device.waitForIdle(IDLE_TIMEOUT_MS)
}

// ---- journey 2: home scroll -----------------------------------------------------------------------
/** RIGHT/LEFT along the first row, then down three rows, then back along that row. */
fun MacrobenchmarkScope.scrollHome() {
    device.press(times = 10) { pressDPadLeft() } // RTL: LEFT = forward
    device.press(times = 3) { pressDPadDown() }
    device.press(times = 5) { pressDPadRight() } // RTL: RIGHT = back
}

// ---- journey 3: open details ----------------------------------------------------------------------
/** OK on the focused poster, wait for the details screen, Back to home. */
fun MacrobenchmarkScope.openDetailsAndBack() {
    // "Continue watching" cards are wide and resume playback on OK; step down to a poster row first.
    if (device.focusedNode()?.isWide() == true) device.press { pressDPadDown() }
    device.press(settleMs = 0) { pressDPadCenter() }
    device.waitForScreen(UiHooks.DETAILS_SCREEN, DETAILS_WAIT_MS)
    device.press(settleMs = 0) { pressBack() }
    waitForHomeRows()
}

// ---- journey 4: browse grid -----------------------------------------------------------------------
/** Up to the top bar, «فیلم» tab, scroll the poster grid down six rows, Back to home. */
fun MacrobenchmarkScope.browseMovies() {
    // Optional journey until the UI exposes test tags (docs/perf-budget.md §UI hooks): skip if the
    // top-bar heuristic can't find the tab, so profile generation never fails on it.
    if (!device.focusTopBarTab(TAB_MOVIES)) return
    device.press(settleMs = BROWSE_OPEN_MS) { pressDPadCenter() }
    // Tolerant on purpose: the grid's focus heuristic (focused card below the header) is not reliable on
    // every emulator; the scroll below still exercises the grid code paths for the profile.
    pollUntil(GRID_TIMEOUT_MS) { device.cardFocusedBelow(BROWSE_HEADER_FRACTION) }
    device.press(times = 6) { pressDPadDown() }
    device.press(settleMs = 0) { pressBack() }
    waitForHomeRows()
}

// ---- helpers --------------------------------------------------------------------------------------
/** [times] key presses, each followed by an idle wait and a short pause. */
private fun UiDevice.press(times: Int = 1, settleMs: Long = KEY_SETTLE_MS, key: UiDevice.() -> Unit) {
    repeat(times) {
        key()
        waitForIdle(IDLE_TIMEOUT_MS)
        if (settleMs > 0) SystemClock.sleep(settleMs)
    }
}

private fun pollUntil(timeoutMs: Long, condition: () -> Boolean): Boolean {
    val deadline = SystemClock.elapsedRealtime() + timeoutMs
    while (true) {
        if (condition()) return true
        if (SystemClock.elapsedRealtime() >= deadline) return false
        SystemClock.sleep(POLL_MS)
    }
}

/**
 * Waits for the screen's test tag if the UI has the hook, otherwise just for [fallbackMs] (bounded
 * sleep), then for idle.
 */
private fun UiDevice.waitForScreen(tag: String, fallbackMs: Long) {
    pollUntil(fallbackMs) { hasObject(By.res(tag)) }
    waitForIdle(IDLE_TIMEOUT_MS)
}

/**
 * The focused Compose node. The Compose host view is "focused" too (full screen), so of all focused
 * nodes of the app the smallest one is the card, tab or chip that really has focus.
 */
private fun UiDevice.focusedNode(): UiObject2? = runCatching {
    findObjects(By.pkg(TARGET_PACKAGE).focused(true)).minByOrNull { it.visibleBounds.area() }
}.getOrNull()

private fun Rect.area(): Long = width().toLong() * height().toLong()

private fun UiObject2.isWide(): Boolean = runCatching { visibleBounds.let { it.width() > it.height() * 1.2f } }
    .getOrDefault(false)

/** True when a card-sized node whose centre lies below [topFraction] of the screen height has focus. */
private fun UiDevice.cardFocusedBelow(topFraction: Float): Boolean {
    val bounds = focusedNode()?.let { runCatching { it.visibleBounds }.getOrNull() } ?: return false
    val screenArea = displayWidth.toLong() * displayHeight.toLong()
    return bounds.area() < screenArea * MAX_CARD_AREA_FRACTION && bounds.centerY() > displayHeight * topFraction
}

/**
 * Moves focus to the top bar tab [label]: UP until the focus is level with the bar, then sideways
 * (RTL: LEFT is forward) until the focused node contains the tab. Works from any row.
 */
private fun UiDevice.focusTopBarTab(label: String): Boolean {
    repeat(MAX_FOCUS_STEPS) {
        val tab = runCatching { findObject(By.text(label))?.visibleBounds }.getOrNull() ?: return false
        val focus = focusedNode()?.let { runCatching { it.visibleBounds }.getOrNull() }
        when {
            focus == null -> press { pressDPadUp() }
            focus.contains(tab.centerX(), tab.centerY()) -> return true
            focus.centerY() > tab.bottom -> press { pressDPadUp() } // still in the rows below the bar
            tab.centerX() < focus.centerX() -> press { pressDPadLeft() }
            else -> press { pressDPadRight() }
        }
    }
    return false
}
